declare(strict_types=1);require_once dirname(__DIR__,2).'/auth_check.php';require_once dirname(__DIR__,2).'/model/Database.php';require_once dirname(__DIR__,2).'/services/MeetingDailyFollowupService.php';require_once dirname(__DIR__,2).'/vendor/autoload.php';require_once dirname(__DIR__,2).'/model/CompanyPdfTemplate.php';
class MeetingTrackingSelectionPdf extends TCPDF{use CompanyPdfTemplate;public function Header():void{$this->drawCompanyPdfHeader();}public function Footer():void{$this->drawCompanyPdfFooter();}}
$service=new MeetingDailyFollowupService(Database::getConnection());$keys=(array)($_SESSION['meeting_followup_export_keys']??[]);unset($_SESSION['meeting_followup_export_keys']);$rows=$service->rowsByKeys($keys);$doc='FIN-REU-PIL-'.date('Ymd-His');$pdf=new MeetingTrackingSelectionPdf('L','mm','A4',true,'UTF-8',false);$pdf->companyPdfTitle='Suivi des engagements de réunion';$pdf->companyPdfType='État de pilotage';$pdf->companyPdfId=$doc;$pdf->companyPdfCode='FIN-REU-PIL';$pdf->companyPdfQrPayload=json_encode(['document'=>$doc,'count'=>count($rows)],JSON_UNESCAPED_UNICODE);$pdf->SetMargins(10,38,10);$pdf->SetAutoPageBreak(true,25);$pdf->AddPage();$pdf->SetY(40);
